-- ============================================================================
-- Core flow definition tables
-- Flows table - stores flow definitions
CREATE TABLE pgflow.flows (
  flow_slug TEXT PRIMARY KEY NOT NULL, -- Unique identifier for the flow
  opt_max_attempts INT NOT NULL DEFAULT 3,
  opt_base_delay INT NOT NULL DEFAULT 1,
  opt_timeout INT NOT NULL DEFAULT 60,
  -- Deployment metadata, persisted separately from the shape (#651):
  -- 'flow' routes every step to lower(flow_slug), 'step' gives every step
  -- its own generated private queue.
  queue_mode TEXT NOT NULL DEFAULT 'flow',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT slug_is_valid CHECK (pgflow.is_valid_slug (flow_slug)),
  CONSTRAINT opt_max_attempts_is_nonnegative CHECK (opt_max_attempts >= 0),
  CONSTRAINT opt_base_delay_is_nonnegative CHECK (opt_base_delay >= 0),
  CONSTRAINT opt_timeout_is_positive CHECK (opt_timeout > 0),
  CONSTRAINT queue_mode_is_valid CHECK (queue_mode IN ('flow', 'step'))
);


-- Steps table - stores individual steps within flows
CREATE TABLE pgflow.steps (
  flow_slug TEXT NOT NULL REFERENCES pgflow.flows (flow_slug),
  step_slug TEXT NOT NULL,
  -- Canonical queue this step's tasks are dispatched to (#650, #651):
  -- 'flow' mode routes every step to lower(flow_slug); 'step' mode routes
  -- each step to its generated private queue (_derive_queue_routes).
  queue_name TEXT NOT NULL,
  step_type TEXT NOT NULL DEFAULT 'single',
  step_index INT NOT NULL DEFAULT 0,
  deps_count INT NOT NULL DEFAULT 0 CHECK (deps_count >= 0),
  opt_max_attempts INT,
  opt_base_delay INT,
  opt_timeout INT,
  opt_start_delay INT,
  required_input_pattern JSONB, -- JSON pattern for @> containment check (if)
  forbidden_input_pattern JSONB, -- JSON pattern for NOT @> containment check (ifNot)
  CONSTRAINT required_input_pattern_is_object CHECK (
    required_input_pattern IS NULL
    OR jsonb_typeof(required_input_pattern) = 'object'
  ),
  CONSTRAINT forbidden_input_pattern_is_object CHECK (
    forbidden_input_pattern IS NULL
    OR jsonb_typeof(forbidden_input_pattern) = 'object'
  ),
  when_unmet TEXT NOT NULL DEFAULT 'skip', -- What to do when condition not met (skip is natural default)
  when_exhausted TEXT NOT NULL DEFAULT 'fail', -- What to do when handler fails after retries
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (flow_slug, step_slug),
  UNIQUE (flow_slug, step_index), -- Ensure step_index is unique within a flow
  CHECK (pgflow.is_valid_slug (step_slug)),
  CONSTRAINT queue_name_is_valid CHECK (pgflow.is_valid_queue_name (queue_name)),
  CHECK (step_type IN ('single', 'map')),
  CONSTRAINT opt_max_attempts_is_nonnegative CHECK (
    opt_max_attempts IS NULL
    OR opt_max_attempts >= 0
  ),
  CONSTRAINT opt_base_delay_is_nonnegative CHECK (
    opt_base_delay IS NULL
    OR opt_base_delay >= 0
  ),
  CONSTRAINT opt_timeout_is_positive CHECK (
    opt_timeout IS NULL
    OR opt_timeout > 0
  ),
  CONSTRAINT opt_start_delay_is_nonnegative CHECK (
    opt_start_delay IS NULL
    OR opt_start_delay >= 0
  ),
  CONSTRAINT when_unmet_is_valid CHECK (when_unmet IN ('fail', 'skip', 'skip-cascade')),
  CONSTRAINT when_exhausted_is_valid CHECK (when_exhausted IN ('fail', 'skip', 'skip-cascade'))
);


-- Dependencies table - stores relationships between steps
CREATE TABLE pgflow.deps (
  flow_slug TEXT NOT NULL REFERENCES pgflow.flows (flow_slug),
  dep_slug TEXT NOT NULL, -- slug of the dependency
  step_slug TEXT NOT NULL, -- slug of the dependent
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (flow_slug, dep_slug, step_slug),
  FOREIGN key (flow_slug, dep_slug) REFERENCES pgflow.steps (flow_slug, step_slug),
  FOREIGN key (flow_slug, step_slug) REFERENCES pgflow.steps (flow_slug, step_slug),
  CHECK (dep_slug != step_slug) -- Prevent self-dependencies
);


CREATE INDEX if NOT EXISTS idx_deps_by_flow_step ON pgflow.deps (flow_slug, step_slug);


CREATE INDEX if NOT EXISTS idx_deps_by_flow_dep ON pgflow.deps (flow_slug, dep_slug);


-- Case-only duplicate step slugs within one flow normalize to the same
-- generated queue name and are rejected (#651).
CREATE UNIQUE INDEX if NOT EXISTS idx_steps_normalized_slug ON pgflow.steps (flow_slug, lower(step_slug));


-- Two concrete flows must not address the same normalized default queue (#650).
-- The expression index also rejects direct SQL creation of conflicting flows.
CREATE UNIQUE INDEX if NOT EXISTS idx_flows_normalized_slug ON pgflow.flows (lower(flow_slug));


