-- ============================================================================
-- Mark Worker Stopped
-- Sets stopped_at timestamp on a worker row for graceful shutdown signaling
CREATE OR REPLACE FUNCTION pgflow.mark_worker_stopped (worker_id UUID) returns void language sql AS $$
  update pgflow.workers
  set stopped_at = clock_timestamp()
  where workers.worker_id = mark_worker_stopped.worker_id;
$$;


COMMENT ON function pgflow.mark_worker_stopped (UUID) IS 'Marks a worker as stopped for graceful shutdown. Called by workers on beforeunload.';


-- ============================================================================
-- Source: 0059_function_ensure_workers.sql
-- ============================================================================
-- AZA PostgreSQL Vault Secret Compatibility
-- Reads Supabase Vault secrets without binding pgflow schema installation to vault.decrypted_secrets.
CREATE OR REPLACE FUNCTION pgflow.aza_vault_secret (secret_name TEXT) returns TEXT language plpgsql stable
SET
  search_path = '' AS $$
DECLARE
  secret_value TEXT;
BEGIN
  IF to_regclass('vault.decrypted_secrets') IS NULL THEN
    RETURN NULL;
  END IF;

  EXECUTE $query$
    SELECT nullif(decrypted_secret, '')
    FROM vault.decrypted_secrets
    WHERE name = $1
    LIMIT 1
  $query$
  INTO secret_value
  USING secret_name;

  RETURN secret_value;
END;
$$;


COMMENT ON function pgflow.aza_vault_secret (TEXT) IS 'Reads a Supabase Vault secret when vault.decrypted_secrets exists; returns NULL when Vault is not installed in this database.';


-- Ensure Workers
-- Returns which worker functions should be invoked, makes HTTP requests, and updates last_invoked_at
-- Called by cron job to keep workers running
CREATE OR REPLACE FUNCTION pgflow.ensure_workers () returns TABLE (function_name TEXT, invoked BOOLEAN, request_id BIGINT) language sql AS $$
  with
    -- Detect environment
    env as (
      select pgflow.is_local() as is_local
    ),

    -- Get credentials: Local mode uses hardcoded URL, production uses vault secrets
    -- Empty strings are treated as NULL using nullif()
    -- pgflow_auth_secret takes priority over supabase_service_role_key for production auth
    credentials as (
      select
        case
          when (select is_local from env) then null
          else coalesce(
            pgflow.aza_vault_secret('pgflow_auth_secret'),
            pgflow.aza_vault_secret('supabase_service_role_key')
          )
        end as service_role_key,
        case
          when (select is_local from env) then 'http://kong:8000/functions/v1'
          else 'https://' || pgflow.aza_vault_secret('supabase_project_id') || '.supabase.co/functions/v1'
        end as base_url
    ),

    -- Only HTTP-started worker functions are supervised via HTTP pings.
    http_worker_functions as (
      select wf.function_name, wf.debounce, wf.last_invoked_at
      from pgflow.worker_functions as wf
      where wf.enabled = true
        and wf.start_mode = 'http'
    ),

    -- Find functions that pass the debounce check
    debounce_passed as (
      select wf.function_name, wf.debounce
      from http_worker_functions as wf
      where wf.last_invoked_at is null
        or wf.last_invoked_at < now() - wf.debounce
    ),

    -- Find functions that have at least one alive worker
    functions_with_alive_workers as (
      select distinct w.function_name
      from pgflow.workers as w
      inner join debounce_passed as dp on w.function_name = dp.function_name
      where w.stopped_at is null
        and w.deprecated_at is null
        and w.last_heartbeat_at > now() - dp.debounce
    ),

    -- Determine which functions should be invoked
    -- Local mode: all enabled functions (bypass debounce AND alive workers check)
    -- Production mode: only functions that pass debounce AND have no alive workers
    functions_to_invoke as (
      select wf.function_name
      from http_worker_functions as wf
      where pgflow.is_local() = true  -- Local: all enabled HTTP functions
        or (
          -- Production: debounce + no alive workers
          wf.function_name in (select dp.function_name from debounce_passed as dp)
          and wf.function_name not in (select faw.function_name from functions_with_alive_workers as faw)
        )
    ),

    -- Make HTTP requests and capture request_ids
    http_requests as (
      select
        fti.function_name,
        net.http_post(
          url => c.base_url || '/' || fti.function_name,
          headers => case
            when e.is_local then '{}'::jsonb
            else jsonb_build_object(
              'Content-Type', 'application/json',
              'Authorization', 'Bearer ' || c.service_role_key
            )
          end,
          body => '{}'::jsonb
        ) as request_id
      from functions_to_invoke as fti
      cross join credentials as c
      cross join env as e
      where c.base_url is not null
        and (e.is_local or c.service_role_key is not null)
    ),

    -- Update last_invoked_at for invoked functions
    updated as (
      update pgflow.worker_functions as wf
      set last_invoked_at = clock_timestamp()
      from http_requests as hr
      where wf.function_name = hr.function_name
      returning wf.function_name
    )

  select u.function_name, true as invoked, hr.request_id
  from updated as u
  inner join http_requests as hr on u.function_name = hr.function_name
$$;


COMMENT ON function pgflow.ensure_workers () IS 'Ensures worker functions are running by pinging them via HTTP when needed.
In local mode: pings ALL enabled functions (ignores debounce AND alive workers check).
In production mode: only pings functions that pass debounce AND have no alive workers.
Debounce: skips functions pinged within their debounce interval (production only).
Credentials: Uses Vault secrets (pgflow_auth_secret with fallback to supabase_service_role_key, supabase_project_id) or local fallbacks.
URL is built from project_id: https://{project_id}.supabase.co/functions/v1
Returns request_id from pg_net for each HTTP request made.';


-- ============================================================================
-- Source: 0060_function_cleanup_ensure_workers_logs.sql
-- ============================================================================
-- Cleanup Ensure Workers Logs
-- Cleans up old cron job run details to prevent the table from growing indefinitely.
-- Note: net._http_response is automatically cleaned by pg_net (6 hour TTL), so we only clean cron logs.
CREATE OR REPLACE FUNCTION pgflow.cleanup_ensure_workers_logs (retention_hours INTEGER DEFAULT 24) returns TABLE (cron_deleted BIGINT) language plpgsql security definer
SET
  search_path = pgflow,
  pg_temp AS $$
DECLARE
  deleted_count BIGINT;
BEGIN
  IF to_regclass('cron.job_run_details') IS NULL THEN
    RETURN QUERY SELECT 0::BIGINT;
    RETURN;
  END IF;

  EXECUTE 'DELETE FROM cron.job_run_details WHERE end_time < now() - make_interval(hours => $1)'
  USING retention_hours;
  GET DIAGNOSTICS deleted_count = ROW_COUNT;
  RETURN QUERY SELECT deleted_count;
END;
$$;


COMMENT ON function pgflow.cleanup_ensure_workers_logs (INTEGER) IS 'Cleans up old cron job run details to prevent table growth.
Default retention is 24 hours. HTTP response logs (net._http_response) are
automatically cleaned by pg_net with a 6-hour TTL, so they are not cleaned here.
Returns 0 when pg_cron is configured in another database and cron.job_run_details
is absent from the current database.
This function follows the standard pg_cron maintenance pattern recommended by
AWS RDS, Neon, and Supabase documentation.';


-- ============================================================================
-- Source: 0060_tables_runtime.sql
-- ============================================================================
-- Runtime State Tables
-- Runs table - tracks flow execution instances
CREATE TABLE pgflow.runs (
  run_id UUID PRIMARY KEY NOT NULL DEFAULT gen_random_uuid(),
  flow_slug TEXT NOT NULL REFERENCES pgflow.flows (flow_slug), -- denormalized
  status TEXT NOT NULL DEFAULT 'started',
  input JSONB NOT NULL,
  output JSONB,
  remaining_steps INT NOT NULL DEFAULT 0 CHECK (remaining_steps >= 0),
  started_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  completed_at TIMESTAMPTZ,
  failed_at TIMESTAMPTZ,
  CONSTRAINT completed_at_or_failed_at CHECK (
    NOT (
      completed_at IS NOT NULL
      AND failed_at IS NOT NULL
    )
  ),
  CONSTRAINT completed_at_is_after_started_at CHECK (
    completed_at IS NULL
    OR completed_at >= started_at
  ),
  CONSTRAINT failed_at_is_after_started_at CHECK (
    failed_at IS NULL
    OR failed_at >= started_at
  ),
  CONSTRAINT status_is_valid CHECK (status IN ('started', 'failed', 'completed'))
);


CREATE INDEX if NOT EXISTS idx_runs_flow_slug ON pgflow.runs (flow_slug);


CREATE INDEX if NOT EXISTS idx_runs_status ON pgflow.runs (status);


CREATE INDEX if NOT EXISTS idx_runs_started_at ON pgflow.runs (started_at);


-- Step states table - tracks the state of individual steps within a run
CREATE TABLE pgflow.step_states (
  flow_slug TEXT NOT NULL REFERENCES pgflow.flows (flow_slug),
  run_id UUID NOT NULL REFERENCES pgflow.runs (run_id),
  step_slug TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'created',
  remaining_tasks INT NULL, -- NULL = not started, >0 = active countdown
  initial_tasks INT NULL CHECK (
    initial_tasks IS NULL
    OR initial_tasks >= 0
  ),
  remaining_deps INT NOT NULL DEFAULT 0 CHECK (remaining_deps >= 0),
  output JSONB, -- Step output: stored atomically with status=completed transition
  error_message TEXT,
  skip_reason TEXT, -- Why step was skipped: condition_unmet, handler_failed, dependency_skipped
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  started_at TIMESTAMPTZ,
  completed_at TIMESTAMPTZ,
  failed_at TIMESTAMPTZ,
  skipped_at TIMESTAMPTZ,
  PRIMARY KEY (run_id, step_slug),
  FOREIGN key (flow_slug, step_slug) REFERENCES pgflow.steps (flow_slug, step_slug),
  CONSTRAINT status_is_valid CHECK (status IN ('created', 'started', 'completed', 'failed', 'skipped')),
  CONSTRAINT status_and_remaining_tasks_match CHECK (
    status != 'completed'
    OR remaining_tasks = 0
  ),
  -- Add constraint to ensure remaining_tasks is only set when step has started
  CONSTRAINT remaining_tasks_state_consistency CHECK (
    remaining_tasks IS NULL
    OR status NOT IN ('created', 'skipped')
  ),
  CONSTRAINT initial_tasks_known_when_started CHECK (
    status != 'started'
    OR initial_tasks IS NOT NULL
  ),
  -- Output is only allowed for completed steps (or NULL for steps that haven't completed)
  -- Note: allows status=completed with output=NULL for single steps that return NULL
  CONSTRAINT output_only_for_completed_or_null CHECK (
    output IS NULL
    OR status = 'completed'
  ),
  -- skip_reason is required for skipped status and forbidden for other statuses
  CONSTRAINT skip_reason_matches_status CHECK (
    (
      status = 'skipped'
      AND skip_reason IS NOT NULL
    )
    OR (
      status != 'skipped'
      AND skip_reason IS NULL
    )
  ),
  CONSTRAINT completed_at_or_failed_at_or_skipped_at CHECK (
    (
      CASE
        WHEN completed_at IS NOT NULL THEN 1
        ELSE 0
      END + CASE
        WHEN failed_at IS NOT NULL THEN 1
        ELSE 0
      END + CASE
        WHEN skipped_at IS NOT NULL THEN 1
        ELSE 0
      END
    ) <= 1
  ),
  CONSTRAINT started_at_is_after_created_at CHECK (
    started_at IS NULL
    OR started_at >= created_at
  ),
  CONSTRAINT completed_at_is_after_started_at CHECK (
    completed_at IS NULL
    OR completed_at >= started_at
  ),
  CONSTRAINT failed_at_is_after_started_at CHECK (
    failed_at IS NULL
    OR failed_at >= started_at
  ),
  CONSTRAINT skipped_at_is_after_created_at CHECK (
    skipped_at IS NULL
    OR skipped_at >= created_at
  )
);


CREATE INDEX if NOT EXISTS idx_step_states_ready ON pgflow.step_states (run_id, status, remaining_deps)
WHERE
  status = 'created'
  AND remaining_deps = 0;


CREATE INDEX if NOT EXISTS idx_step_states_failed ON pgflow.step_states (run_id, step_slug)
WHERE
  status = 'failed';


CREATE INDEX if NOT EXISTS idx_step_states_skipped ON pgflow.step_states (run_id, step_slug)
WHERE
  status = 'skipped';


CREATE INDEX if NOT EXISTS idx_step_states_flow_slug ON pgflow.step_states (flow_slug);


CREATE INDEX if NOT EXISTS idx_step_states_run_id ON pgflow.step_states (run_id);


-- Step tasks table - tracks units of work for step
CREATE TABLE pgflow.step_tasks (
  flow_slug TEXT NOT NULL REFERENCES pgflow.flows (flow_slug),
  run_id UUID NOT NULL REFERENCES pgflow.runs (run_id),
  step_slug TEXT NOT NULL,
  -- Snapshot of steps.queue_name taken at task creation (#650).
  -- Runtime code never changes this value; PGMQ message IDs are queue-scoped,
  -- so a task's message identity is (queue_name, message_id).
  queue_name TEXT NOT NULL,
  message_id BIGINT,
  task_index INT NOT NULL DEFAULT 0,
  status TEXT NOT NULL DEFAULT 'queued',
  attempts_count INT NOT NULL DEFAULT 0,
  error_message TEXT,
  output JSONB,
  queued_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  started_at TIMESTAMPTZ,
  completed_at TIMESTAMPTZ,
  failed_at TIMESTAMPTZ,
  last_worker_id UUID REFERENCES pgflow.workers (worker_id) ON DELETE SET NULL,
  -- Requeue tracking columns
  requeued_count INT NOT NULL DEFAULT 0,
  last_requeued_at TIMESTAMPTZ,
  permanently_stalled_at TIMESTAMPTZ,
  CONSTRAINT step_tasks_pkey PRIMARY KEY (run_id, step_slug, task_index),
  FOREIGN key (run_id, step_slug) REFERENCES pgflow.step_states (run_id, step_slug),
  CONSTRAINT valid_status CHECK (status IN ('queued', 'started', 'completed', 'failed', 'skipped', 'cancelled')),
  CONSTRAINT output_valid_only_for_completed CHECK (
    output IS NULL
    OR status IN ('completed', 'failed')
  ),
  CONSTRAINT attempts_count_nonnegative CHECK (attempts_count >= 0),
  CONSTRAINT completed_at_or_failed_at CHECK (
    NOT (
      completed_at IS NOT NULL
      AND failed_at IS NOT NULL
    )
  ),
  CONSTRAINT completed_at_is_after_queued_at CHECK (
    completed_at IS NULL
    OR completed_at >= queued_at
  ),
  CONSTRAINT failed_at_is_after_queued_at CHECK (
    failed_at IS NULL
    OR failed_at >= queued_at
  ),
  CONSTRAINT started_at_is_after_queued_at CHECK (
    started_at IS NULL
    OR started_at >= queued_at
  ),
  CONSTRAINT completed_at_is_after_started_at CHECK (
    completed_at IS NULL
    OR started_at IS NULL
    OR completed_at >= started_at
  ),
  CONSTRAINT failed_at_is_after_started_at CHECK (
    failed_at IS NULL
    OR started_at IS NULL
    OR failed_at >= started_at
  ),
  CONSTRAINT queue_name_is_valid CHECK (pgflow.is_valid_queue_name (queue_name))
);


-- A message ID identifies at most one task per queue (#650).
-- NULL message_ids (pre-dispatch rows) are not part of the identity.
-- This index also serves queue-scoped message lookups for claims and pruning,
-- replacing the former message_id-only index.
CREATE UNIQUE INDEX if NOT EXISTS idx_step_tasks_queue_message ON pgflow.step_tasks (queue_name, message_id)
WHERE
  message_id IS NOT NULL;


CREATE INDEX if NOT EXISTS idx_step_tasks_queued ON pgflow.step_tasks (run_id, step_slug)
WHERE
  status = 'queued';


CREATE INDEX if NOT EXISTS idx_step_tasks_completed ON pgflow.step_tasks (run_id, step_slug)
WHERE
  status = 'completed';


CREATE INDEX if NOT EXISTS idx_step_tasks_failed ON pgflow.step_tasks (run_id, step_slug)
WHERE
  status = 'failed';


CREATE INDEX if NOT EXISTS idx_step_tasks_flow_run_step ON pgflow.step_tasks (flow_slug, run_id, step_slug);


-- New indexes for refactored polling behavior
CREATE INDEX if NOT EXISTS idx_step_tasks_started ON pgflow.step_tasks (started_at)
WHERE
  status = 'started';


CREATE INDEX if NOT EXISTS idx_step_tasks_queued_msg ON pgflow.step_tasks (message_id)
WHERE
  status = 'queued';


CREATE INDEX if NOT EXISTS idx_step_tasks_last_worker ON pgflow.step_tasks (last_worker_id)
WHERE
  status = 'started';


-- ============================================================================
-- Source: 0061_function_setup_ensure_workers_cron.sql
-- ============================================================================
-- Setup Ensure Workers Cron
-- Sets up cron jobs for worker management: ensure_workers (configurable interval) and cleanup_logs (hourly)
CREATE OR REPLACE FUNCTION pgflow.setup_ensure_workers_cron (cron_interval TEXT DEFAULT '1 second') returns TEXT language plpgsql security definer
SET
  search_path = pgflow,
  pg_temp AS $$
declare
  ensure_workers_job_id bigint;
  cleanup_job_id bigint;
begin
  IF to_regprocedure('cron.schedule(text,text,text)') IS NULL THEN
    RETURN 'pg_cron is not available in this database; skipped pgflow worker cron setup';
  END IF;

  -- Remove existing jobs if they exist (ignore errors if not found)
  begin
    perform cron.unschedule('pgflow_ensure_workers');
  exception when others then
    -- Job doesn't exist, continue
  end;

  begin
    perform cron.unschedule('pgflow_cleanup_logs');
  exception when others then
    -- Job doesn't exist, continue
  end;

  -- Schedule ensure_workers job with the specified interval
  ensure_workers_job_id := cron.schedule(
    job_name => 'pgflow_ensure_workers',
    schedule => setup_ensure_workers_cron.cron_interval,
    command => 'select pgflow.ensure_workers()'
  );

  -- Schedule cleanup job to run hourly
  cleanup_job_id := cron.schedule(
    job_name => 'pgflow_cleanup_logs',
    schedule => '0 * * * *',
    command => 'select pgflow.cleanup_ensure_workers_logs()'
  );

  return format(
    'Scheduled pgflow_ensure_workers (every %s, job_id=%s) and pgflow_cleanup_logs (hourly, job_id=%s)',
    setup_ensure_workers_cron.cron_interval,
    ensure_workers_job_id,
    cleanup_job_id
  );
end;
$$;


COMMENT ON function pgflow.setup_ensure_workers_cron (TEXT) IS 'Sets up cron jobs for worker management.
Schedules pgflow_ensure_workers at the specified cron_interval (default: 1 second) to keep workers running.
Schedules pgflow_cleanup_logs hourly to clean up old cron job logs.
Replaces existing jobs if they exist (idempotent).
Returns a skipped message when pg_cron is configured in another database.
Returns a confirmation message with job IDs.';


-- ============================================================================
-- Source: 0062_function_requeue_stalled_tasks.sql
-- ============================================================================
-- Requeue stalled tasks that have been in 'started' status longer than their effective
-- timeout (step override with flow fallback) + 30s buffer. This matches the effective
-- timeout used by start_tasks() for PGMQ visibility, without its +2s visibility margin.
-- This handles tasks that got stuck when workers crashed without completing them
CREATE OR REPLACE FUNCTION pgflow.requeue_stalled_tasks () returns INT language plpgsql security definer
SET
  search_path = '' AS $$
declare
  result_count int := 0;
  max_requeues constant int := 3;
begin
  -- Find and requeue stalled tasks (where started_at > effective timeout + 30s buffer)
  -- Tasks with requeued_count >= max_requeues will have their message archived
  -- but status left as 'started' for easy identification via requeued_count column
  -- Eligibility requires the parent run AND parent step to still be 'started':
  -- stale rows on failed runs or terminal steps must not be revived (#645).
  with stalled_tasks as (
    select
      st.run_id,
      st.step_slug,
      st.task_index,
      st.message_id,
      st.queue_name,
      r.flow_slug,
      st.requeued_count
    from pgflow.step_tasks st
    join pgflow.runs r on r.run_id = st.run_id
    join pgflow.step_states ss on ss.run_id = st.run_id and ss.step_slug = st.step_slug
    join pgflow.flows f on f.flow_slug = r.flow_slug
    join pgflow.steps s on s.flow_slug = r.flow_slug and s.step_slug = st.step_slug
    where st.status = 'started'
      and r.status = 'started'
      and ss.status = 'started'
      and st.permanently_stalled_at is null
      and st.started_at < now()
        - (coalesce(s.opt_timeout, f.opt_timeout) * interval '1 second')
        - interval '30 seconds'
    for update of st skip locked
  ),
  -- Separate tasks that can be requeued from those that exceeded max requeues
  to_requeue as (
    select * from stalled_tasks where requeued_count < max_requeues
  ),
  to_archive as (
    select * from stalled_tasks where requeued_count >= max_requeues
  ),
  -- Update tasks that will be requeued
  requeued as (
    update pgflow.step_tasks st
    set
      status = 'queued',
      started_at = null,
      last_worker_id = null,
      requeued_count = st.requeued_count + 1,
      last_requeued_at = now()
    from to_requeue tr
    where st.run_id = tr.run_id
      and st.step_slug = tr.step_slug
      and st.task_index = tr.task_index
    returning tr.queue_name as queue_name, tr.message_id
  ),
  -- Make requeued messages visible immediately (batched per queue, through
  -- the tasks' stored queue snapshots #650; PGMQ message operations
  -- normalize names themselves)
  visibility_reset as (
    select pgflow.set_vt_batch(
      r.queue_name,
      array_agg(r.message_id),
      array_agg(0)  -- all offsets are 0 (immediate visibility)
    )
    from requeued r
    where r.message_id is not null
    group by r.queue_name
  ),
  -- Mark tasks as permanently stalled before archiving
  mark_permanently_stalled as (
    update pgflow.step_tasks st
    set permanently_stalled_at = now()
    from to_archive ta
    where st.run_id = ta.run_id
      and st.step_slug = ta.step_slug
      and st.task_index = ta.task_index
    returning st.run_id
  ),
  -- Archive messages for tasks that exceeded max requeues (batched per queue)
  archived as (
    select pgmq.archive(
      ta.queue_name,
      array_agg(ta.message_id)
    )
    from to_archive ta
    where ta.message_id is not null
    group by ta.queue_name
  ),
  -- Force execution of visibility_reset CTE
  _vr as (select count(*) from visibility_reset),
  -- Force execution of mark_permanently_stalled CTE
  _mps as (select count(*) from mark_permanently_stalled),
  -- Force execution of archived CTE
  _ar as (select count(*) from archived)
  select count(*) into result_count
  from requeued, _vr, _mps, _ar;

  return result_count;
end;
$$;


-- ============================================================================
-- Source: 0063_function_setup_requeue_stalled_tasks_cron.sql
-- ============================================================================
-- Cron setup function for automatic requeue monitoring
CREATE OR REPLACE FUNCTION pgflow.setup_requeue_stalled_tasks_cron (cron_interval TEXT DEFAULT '15 seconds') returns TEXT language plpgsql security definer
SET
  search_path = pgflow,
  pg_temp AS $$
declare
  job_id bigint;
begin
  IF to_regprocedure('cron.schedule(text,text,text)') IS NULL THEN
    RETURN 'pg_cron is not available in this database; skipped pgflow stalled-task cron setup';
  END IF;

  -- Remove existing job if any
  begin
    perform cron.unschedule('pgflow_requeue_stalled_tasks');
  exception
    when others then null;
  end;

  -- Schedule the new job
  job_id := cron.schedule(
    job_name => 'pgflow_requeue_stalled_tasks',
    schedule => setup_requeue_stalled_tasks_cron.cron_interval,
    command => 'select pgflow.requeue_stalled_tasks()'
  );

  return format('Scheduled pgflow_requeue_stalled_tasks (every %s, job_id=%s)',
    setup_requeue_stalled_tasks_cron.cron_interval, job_id);
end;
$$;


COMMENT ON function pgflow.setup_requeue_stalled_tasks_cron (TEXT) IS 'Sets up cron job to automatically requeue stalled tasks.
Schedules pgflow_requeue_stalled_tasks at the specified cron_interval (default: 15 seconds).
Replaces existing job if it exists (idempotent).
Returns a skipped message when pg_cron is configured in another database.
Returns a confirmation message with job ID.';


-- Automatically set up the cron job when migration runs
SELECT
  pgflow.setup_requeue_stalled_tasks_cron ();


-- ============================================================================
-- Source: 0070_function_resolve_step_queue_name.sql
-- ============================================================================
-- Canonical per-step queue-name resolution (#651).
--
-- For a zero-based step index:
--   readable = lower(flow_slug || '__' || step_slug)
--   fallback = lower(flow_slug || '__' || step_index)
--
-- Resolution: readable when it fits MAX 47 characters; otherwise the
-- actual-index fallback when it fits; otherwise the complete flow is
-- rejected. Names are never truncated or hashed. TypeScript mirrors this
-- resolver in @pgflow/dsl (resolveStepQueueName); vectors must stay in sync.
CREATE OR REPLACE FUNCTION pgflow._resolve_step_queue_name (p_flow_slug TEXT, p_step_slug TEXT, p_step_index INT) returns TEXT language plpgsql immutable
SET
  search_path = '' AS $$
declare
  v_readable text := lower(p_flow_slug || '__' || p_step_slug);
  v_fallback text := lower(p_flow_slug || '__' || p_step_index);
  v_shortest text := lower(p_flow_slug || '__0');
begin
  if length(v_readable) <= 47 then
    return v_readable;
  end if;

  if length(v_shortest) > 47 then
    -- The flow slug cannot fit even the shortest possible index suffix.
    raise exception
      'Flow "%" cannot use per-step queues.',
      p_flow_slug
      using detail = format(
        'The shortest required queue "%s" is %s characters; PGMQ allows at most 47.',
        v_shortest, length(v_shortest)
      ),
      hint = 'Shorten the concrete flow slug or use the default single queue.';
  end if;

  if length(v_fallback) <= 47 then
    return v_fallback;
  end if;

  raise exception
    'Cannot derive a queue for step "%" at index % in flow "%".',
    p_step_slug, p_step_index, p_flow_slug
    using detail = format(
      'The readable name is %s characters and the index fallback is %s; PGMQ allows at most 47.',
      length(v_readable), length(v_fallback)
    ),
    hint = 'Shorten the concrete flow slug, shorten the step slug enough for the readable name, or use the default single queue.';
end;
$$;


-- ============================================================================
-- Source: 0075_function_derive_queue_routes.sql
-- ============================================================================
-- Derive the complete ordered queue route map from a shape and a queue
-- mode (#651). This is the one canonical derivation: startup compilation is
-- authoritative and callers may only supply a map that matches it exactly.
--
-- Returns an ordered jsonb array [{stepSlug, queueName}] by shape
-- ordinality (zero-based step_index). In 'step' mode every name is resolved
-- through _resolve_step_queue_name, validated with the installed
-- pgmq.validate_queue_name(), and checked for duplicates. In 'flow' mode
-- every step routes to lower(flow_slug).
CREATE OR REPLACE FUNCTION pgflow._derive_queue_routes (p_flow_slug TEXT, p_shape JSONB, p_queue_mode TEXT) returns JSONB language plpgsql
-- Volatile like the pgmq.validate_queue_name() call it performs: an
-- IMMUTABLE label on a function that runs PGMQ validation would mislead
-- the planner about what the call can do.
volatile
SET
  search_path = '' AS $$
declare
  v_step jsonb;
  v_step_slug text;
  v_step_index int;
  v_queue_name text;
  v_routes jsonb := '[]'::jsonb;
  v_seen_normalized_steps text[] := '{}';
  v_seen_step_slugs text[] := '{}';
  v_seen_queues text[] := '{}';
  v_seen_queue_steps text[] := '{}';
begin
  if p_queue_mode not in ('flow', 'step') then
    raise exception 'Unknown queue mode "%".', p_queue_mode
      using hint = 'Queue mode must be ''flow'' or ''step''.';
  end if;

  if p_queue_mode = 'step' and jsonb_array_length(coalesce(p_shape->'steps', '[]'::jsonb)) = 0 then
    raise exception
      'Flow "%" cannot use per-step queues: it has no steps.',
      p_flow_slug
      using detail = 'Per-step queue mode requires at least one step.',
      hint = 'Add a step or keep the flow on the default single queue.';
  end if;

  -- Validate the concrete flow slug and every step slug before route
  -- resolution, collision checks, or PGMQ work: an invalid slug is a
  -- definition error that outranks every queue concern, so a shape with
  -- both problems reports the slug, not the queue.
  if not pgflow.is_valid_slug(p_flow_slug) then
    raise exception
      'Flow slug "%" is not valid.',
      p_flow_slug
      using detail = 'Slugs are 1-128 characters of letters, digits, and single underscores, must start with a letter, cannot end with an underscore, cannot contain ''__'', and cannot be the reserved word ''run''.',
      hint = 'Fix the flow slug in the flow definition.';
  end if;

  for v_step in select * from jsonb_array_elements(coalesce(p_shape->'steps', '[]'::jsonb))
  loop
    v_step_slug := v_step->>'slug';

    if not pgflow.is_valid_slug(v_step_slug) then
      raise exception
        'Step slug "%" in flow "%" is not valid.',
        v_step_slug, p_flow_slug
        using detail = 'Slugs are 1-128 characters of letters, digits, and single underscores, must start with a letter, cannot end with an underscore, cannot contain ''__'', and cannot be the reserved word ''run''.',
        hint = 'Fix the step slug in the flow definition.';
    end if;
  end loop;

  for v_step in select * from jsonb_array_elements(coalesce(p_shape->'steps', '[]'::jsonb))
  loop
    v_step_slug := v_step->>'slug';
    v_step_index := jsonb_array_length(v_routes);

    -- Validate normalized step identity before route resolution. Long
    -- case-only variants can resolve to distinct index fallbacks, so route
    -- collisions alone cannot detect this invalid definition.
    if lower(v_step_slug) = any(v_seen_normalized_steps) then
      raise exception
        'Steps "%" and "%" in flow "%" conflict case-insensitively.',
        v_seen_step_slugs[array_position(v_seen_normalized_steps, lower(v_step_slug))],
        v_step_slug,
        p_flow_slug
        using detail = 'Step slugs must be unique case-insensitively.',
        hint = 'Rename one of the colliding steps.';
    end if;
    v_seen_normalized_steps := v_seen_normalized_steps || lower(v_step_slug);
    v_seen_step_slugs := v_seen_step_slugs || v_step_slug;

    if p_queue_mode = 'step' then
      v_queue_name := pgflow._resolve_step_queue_name(p_flow_slug, v_step_slug, v_step_index);
      perform pgmq.validate_queue_name(v_queue_name);
    else
      v_queue_name := lower(p_flow_slug);
    end if;

    if p_queue_mode = 'step' and v_queue_name = any(v_seen_queues) then
      raise exception
        'Steps "%" and "%" in flow "%" both resolve to queue "%".',
        v_seen_queue_steps[array_position(v_seen_queues, v_queue_name)], v_step_slug, p_flow_slug, v_queue_name
        using detail = 'Generated queue names must be unique per flow.',
        hint = 'Step slugs must be unique case-insensitively; rename one of the colliding steps.';
    end if;

    v_seen_queues := v_seen_queues || v_queue_name;
    v_seen_queue_steps := v_seen_queue_steps || v_step_slug;
    v_routes := v_routes || jsonb_build_object('stepSlug', v_step_slug, 'queueName', v_queue_name);
  end loop;

  return v_routes;
end;
$$;


-- ============================================================================
-- Source: 0076_function_assert_step_queue_available.sql
-- ============================================================================
-- Shared step-queue route preflight (#651): one canonical ownership and
-- listing check for every step-mode queue name, so startup verification and
-- creation cannot diverge.
--
-- Callers must already hold the normalized-flow advisory lock
-- (pg_advisory_xact_lock(1, hashtext(lower(flow_slug)))).
--
-- Rejects:
-- - a queue name routed to by another concrete flow's steps, or defaulted
--   to by another flow-mode flow (cross-flow reference);
-- - an ambiguous case-insensitive match among listed PGMQ queues
--   (external damage), even when this flow's definition owns the route;
-- - an owned route whose PGMQ queue is not listed: pgflow never drops an
--   owned queue itself, so something outside pgflow did (a manual
--   pgmq.drop_queue, a customized prune_data_older_than, or a restore that
--   skipped the pgmq tables) — reject instead of verifying a startup whose
--   polling cannot work.
--
-- Allows one exact listed queue only when the existing definition of this
-- exact flow owns that route (idempotent reuse). A name that is neither
-- listed nor owned is left for the caller to create.
--
-- Returns true when the caller must create the queue.
CREATE OR REPLACE FUNCTION pgflow._assert_step_queue_available (p_flow_slug TEXT, p_queue_name TEXT) returns BOOLEAN language plpgsql volatile
SET
  search_path = '' AS $$
declare
  v_owner_flow_slug text;
  v_listed text[];
begin
  -- A name derived or referenced by another concrete flow is rejected
  select s.flow_slug into v_owner_flow_slug
  from pgflow.steps as s
  where s.queue_name = p_queue_name
    and lower(s.flow_slug) <> lower(p_flow_slug)
  limit 1;

  if v_owner_flow_slug is null then
    select f.flow_slug into v_owner_flow_slug
    from pgflow.flows as f
    where f.queue_mode = 'flow'
      and lower(f.flow_slug) = p_queue_name
      and lower(f.flow_slug) <> lower(p_flow_slug)
    limit 1;
  end if;

  if v_owner_flow_slug is not null then
    raise exception
      'cannot create flow "%": queue "%" is already used by another flow ("%")',
      p_flow_slug, p_queue_name, v_owner_flow_slug
      using detail = 'Generated per-step queue names must belong to exactly one concrete flow.',
      hint = 'Use a different concrete flow slug, or drop the conflicting definition.';
  end if;

  -- Ambiguous normalized matches among listed queues are external damage
  select array_agg(listed.queue_name order by listed.queue_name)
  into v_listed
  from pgmq.list_queues() as listed
  where lower(listed.queue_name) = p_queue_name;

  if v_listed is not null and cardinality(v_listed) > 1 then
    raise exception
      'queue "%" matches multiple listed PGMQ queues (%)',
      p_queue_name, v_listed
      using detail = 'An ambiguous case-insensitive match is external damage.',
      hint = 'Resolve the duplicate queue spellings manually, then retry.';
  end if;

  -- Owned by an existing definition of this exact flow: reuse idempotently.
  -- A verified definition owns every derived route, so its one exact listed
  -- queue is allowed here. An owned route without its listed queue is
  -- external damage: reuse would report the route available while polling
  -- fails, so reject it instead.
  if exists (
    select 1 from pgflow.steps as s
    where s.flow_slug = p_flow_slug and s.queue_name = p_queue_name
  ) then
    if v_listed is null then
      raise exception
        'queue "%" owned by flow "%" is not listed in PGMQ',
        p_queue_name, p_flow_slug
        using detail = 'pgflow never drops an owned queue itself: a manual pgmq.drop_queue, a customized prune_data_older_than, or a restore that skipped the pgmq tables did. Historical task rows still reference message ids from the dropped queue.',
        hint = 'Check why the queue disappeared; if the loss is intended, drop the flow definition and recompile it fresh.';
    end if;

    return false;
  end if;

  if v_listed is not null then
    raise exception
      'cannot create flow "%": queue "%" is already listed in PGMQ and not owned by this flow',
      p_flow_slug, p_queue_name
      using detail = 'A missing definition must not adopt an already listed queue.',
      hint = 'Drop the conflicting queue or use a different concrete flow slug.';
  end if;

  return true;
end;
$$;


